import {heldItems,combineItems} from './model.mjs';
import {combatLobby} from './combat-lobby.mjs';
import {createArena} from './arena-model.mjs';
import {normalizePlayer} from './player-profile.mjs';
import {TowerBattle} from './battle.mjs';
import {trainedFighter,addXP} from './training.mjs';
import {duelRound} from './duel-model.mjs';
const LOBBY='pokeworld-global-queue-v1';
export class Duel extends TowerBattle {
 constructor(g){super(g);this.style=g.state.settings.combatStyle||'classic';this.peer=null;this.conn=null;this.isHost=false;this.searching=false;this.status='';this.coordinator=null;this.waiting=[];this.connectionMap=new Map()}
 render(){return combatLobby(this)}
 clean(){clearTimeout(this.retry);clearTimeout(this.queueTimeout);this.peer?.destroy();this.coordinator?.destroy();this.peer=null;this.coordinator=null;this.conn=null;this.searching=false;this.waiting=[];this.connectionMap.clear()}
 available(){if(!window.Peer){this.g.toast('Le service de connexion est indisponible. Réessaie avec Internet.');return false}return this.g.requireStarter()}
 offer(){return {style:this.style,player:this.g.state.player,keys:this.g.state.team,items:Object.fromEntries(this.g.state.team.map(k=>[k,heldItems(this.g.state,k).map(i=>i.key)])),training:Object.fromEntries(this.g.state.team.map(k=>[k,this.g.state.training[k]||null]))}}
 create(joinCode=null){if(!this.available())return;this.clean();this.isHost=!joinCode;this.status=joinCode?'Connexion au duel…':'Création du duel…';this.peer=new window.Peer();this.peer.on('open',()=>{if(joinCode)this.attach(this.peer.connect(joinCode,{reliable:true}),false);else{this.status='Partage ton code avec un ami.';this.g.render()}});this.peer.on('connection',c=>{if(this.conn?.open||this.active){c.close();return}this.attach(c,true)});this.peer.on('error',e=>{this.status='Connexion impossible : '+e.type;if(this.g.page==='pvp')this.g.render()});this.g.render()}
 attach(c,host){this.conn=c;this.isHost=host;c.on('open',()=>{if(!host)c.send({type:'duel-ready',offer:this.offer()})});c.on('data',d=>this.packet(d));c.on('close',()=>{if(this.active&&!this.data.over){if(this.arenaMode){this.g.arena.stop();this.g.toast('L’adversaire a quitté l’arène.');return}this.status='L’adversaire a quitté le duel.';super.stop();this.g.route('pvp');this.g.toast(this.status)}})}
 async packet(d){if(!d||typeof d.type!=='string')return;if(d.type==='arena-start'&&!this.isHost){this.style='arena';this.searching=false;this.g.arena.mountNetwork(d.state,this);return}if(d.type.startsWith('arena-')){if(this.arenaMode)this.g.arena.receive(d);return}if(d.type==='duel-ready'&&this.isHost&&!this.active&&this.style==='arena'){const mine=this.validate(this.offer()),enemy=this.validate(d.offer);if(!mine.length||!enemy.length)return;const state=createArena([{pid:this.peer.id,...normalizePlayer(this.g.state.player),active:0,mons:mine},{pid:this.conn.peer,...normalizePlayer(d.offer.player),active:0,mons:enemy}],{id:crypto.randomUUID(),ai:false,theme:this.g.state.settings.arenaTheme||'grass',format:this.g.state.settings.arenaFormat||'duel'});this.searching=false;this.conn.send({type:'arena-start',state});this.g.arena.mountNetwork(state,this);return}if(d.type==='duel-ready'&&this.isHost&&!this.active){const enemy=this.validate(d.offer);if(!enemy.length)return;const mine=this.validate(this.offer());this.raw={id:crypto.randomUUID(),turn:1,actions:{},over:false,teams:[{pid:this.peer.id,...normalizePlayer(this.g.state.player),active:0,mons:mine},{pid:this.conn.peer,...normalizePlayer(d.offer.player),active:0,mons:enemy}]};this.conn.send({type:'duel-start',battle:this.raw});this.mountDuel(this.raw)}if(d.type==='duel-start'&&!this.isHost)this.mountDuel(d.battle);if(d.type==='duel-action'&&this.isHost&&d.id===this.raw?.id&&!this.raw.over){const enemy=this.raw.teams.find(t=>t.pid===this.conn.peer);if(this.validAction(enemy,d.action)&&!this.raw.actions[enemy.pid]){this.raw.actions[enemy.pid]=d.action;if(!this.busy)this.resolveDuel()}}if(d.type==='duel-wait'&&!this.isHost&&this.raw?.id===d.id){this.raw.actions=d.actions;this.data=this.view(this.raw);this.updateHud()}if(d.type==='duel-turn'&&!this.isHost&&d.battle.id===this.raw?.id){this.raw=d.battle;await this.play(this.view(d.before),this.mapEvents(d.events),this.view(d.battle),d.battle.sequence||d.battle.turn)}}
 validate(offer){const keys=[...new Set(Array.isArray(offer?.keys)?offer.keys:[])].filter(k=>this.g.dex[parseInt(k)]&&/^\d+s?$/.test(k)).slice(0,6);return keys.map(k=>{const state={training:{[k]:offer.training?.[k]},roster:keys};return trainedFighter(this.g.dex,state,k,combineItems(offer.items?.[k]),50)})}
 view(raw){const me=raw.teams.find(t=>t.pid===this.peer.id),enemy=raw.teams.find(t=>t.pid!==this.peer.id);return{id:raw.id,kind:'duel',floor:0,turn:raw.turn,sequence:raw.sequence,phase:raw.phase,pendingReplacements:(raw.pendingReplacements||[]).map(pid=>pid===this.peer.id?'hero':'boss'),actions:raw.actions[this.peer.id]?{hero:raw.actions[this.peer.id]}:{},over:raw.over,win:raw.winner===this.peer.id,teams:[{...structuredClone(me),pid:'hero',name:'Toi'}],boss:structuredClone(enemy.mons[enemy.active]),field:structuredClone(raw.field||{}),enemyParty:enemy.mons,enemyIndex:enemy.active,trainerName:enemy.name,trainerAvatar:enemy.avatar} }
 mountDuel(raw){this.searching=false;clearTimeout(this.retry);this.raw=structuredClone(raw);super.mount(this.view(raw));this.g.modeRoot.querySelector('.mode-title small').textContent='POKÉWORLD · DUEL EN LIGNE';this.g.modeRoot.querySelector('.mode-title strong').textContent='Dresseur contre dresseur';this.g.modeRoot.querySelector('.boss-health small').textContent='ÉQUIPE ADVERSE · NIVEAU 50';this.g.modeRoot.querySelector('.battle-command-title small').textContent='Chaque joueur choisit une action par tour';this.g.modeRoot.querySelector('[data-act="finish-battle"]').textContent='Retour à l’arène'}
 me(){return this.data.teams[0]}
 validAction(t,a){if(!t||!a||(a.move!==undefined)===(a.swap!==undefined))return false;const pending=this.raw?.pendingReplacements||[];if(pending.length&&(!pending.includes(t?.pid)||!Number.isInteger(a?.swap)))return false;return t&&a&&((Number.isInteger(a.move)&&t.mons[t.active].hp>0&&(t.mons[t.active].moves[a.move]?.left>0||t.mons[t.active].moves[a.move]&&t.mons[t.active].volatile?.charging))||(Number.isInteger(a.swap)&&a.swap!==t.active&&t.mons[a.swap]?.hp>0))}
 act(a){if(!this.active||this.busy||this.raw.over||this.raw.actions[this.peer.id])return;const t=this.raw.teams.find(t=>t.pid===this.peer.id);if(!this.validAction(t,a))return;this.raw.actions[this.peer.id]=a;this.data=this.view(this.raw);if(this.isHost)this.resolveDuel();else{this.conn.send({type:'duel-action',id:this.raw.id,action:a});this.updateHud()}}
 afterPlayback(){if(this.isHost&&Object.keys(this.raw.actions).length)this.resolveDuel()}
 resolveDuel(){const before=structuredClone(this.raw),events=duelRound(this.raw,this.g.chart);if(!events){this.conn.send({type:'duel-wait',id:this.raw.id,actions:this.raw.actions});this.data=this.view(this.raw);this.updateHud();return}this.conn.send({type:'duel-turn',before,events,battle:this.raw});this.play(this.view(before),this.mapEvents(events),this.view(this.raw),this.raw.sequence||this.raw.turn)}
 mapEvents(events){return events.map(e=>{if(e.kind==='swap'&&e.pid!==this.peer.id)return{kind:'enemy-swap',mon:structuredClone(e.mon||this.raw.teams.find(t=>t.pid===e.pid).mons.find(m=>m.key===e.key))};return{...e,pid:e.pid===this.peer.id?'hero':'boss',source:e.source===this.peer.id?'hero':'boss',target:e.target===this.peer.id?'hero':'boss'}})}
 finishResult(){const g=this.g,b=this.data;g.audio.music.setScene(b.win?'victory':'defeat');if(!this.rewarded.has(b.id)){this.rewarded.add(b.id);g.state.modeStats.duels++;if(b.win)g.state.modeStats.duelWins++;g.state.candies++;g.state.team.forEach(k=>addXP(g.state,k,b.win?40:20));g.save()}const end=g.modeRoot.querySelector('.battle-end');end.hidden=false;g.modeRoot.querySelector('#battle-end-label').textContent=b.win?'UNE BELLE VICTOIRE':'LE DUEL EST TERMINÉ';g.modeRoot.querySelector('#battle-end-title').textContent=b.win?'Victoire !':'Défaite';g.modeRoot.querySelector('#battle-end-reward').textContent='+1 bonbon · Expérience gagnée par ton équipe'}
 stop(){const c=this.conn;this.active=false;this.clean();super.stop();c?.close();this.g.route('pvp')}
 search(){if(!this.available())return;this.clean();this.searching=true;this.status='Recherche de vrais joueurs…';this.peer=new window.Peer();this.peer.on('connection',c=>{if(c.metadata?.match){this.attach(c,false)}});this.peer.on('open',()=>this.queueConnect());this.peer.on('error',e=>{this.status='Réseau indisponible : '+e.type;if(this.g.page==='pvp')this.g.render()});this.g.render()}
 queueConnect(){if(!this.searching)return;const q=this.peer.connect(LOBBY+(this.style==='arena'?'-arena-'+(this.g.state.settings.arenaFormat||'duel'):''),{reliable:true,metadata:{queue:true}});let opened=false;const elect=()=>{if(this.searching&&!opened)this.electCoordinator()};q.on('open',()=>{opened=true;clearTimeout(this.queueTimeout);q.send({type:'queue-join',id:this.peer.id});this.status='Dans la file mondiale. En attente d’un autre dresseur.';if(this.g.page==='pvp')this.g.render()});q.on('data',d=>{if(d.type==='match'&&this.searching){this.searching=false;this.status='Adversaire trouvé !';if(d.host)this.attach(this.peer.connect(d.opponent,{reliable:true,metadata:{match:true}}),true)}});q.on('error',elect);q.on('close',()=>{if(this.searching)this.retry=setTimeout(()=>this.queueConnect(),1500)});this.queueTimeout=setTimeout(elect,3000)}
 electCoordinator(){if(this.coordinator||!this.searching)return;const server=this.coordinator=new window.Peer(LOBBY+(this.style==='arena'?'-arena-'+(this.g.state.settings.arenaFormat||'duel'):''));server.on('open',()=>this.queueConnect());server.on('error',()=>{server.destroy();this.coordinator=null;this.retry=setTimeout(()=>this.queueConnect(),1500)});server.on('connection',c=>{c.on('data',d=>{if(d.type!=='queue-join'||d.id!==c.peer)return;this.connectionMap.set(c.peer,c);this.waiting=this.waiting.filter(id=>this.connectionMap.get(id)?.open);if(!this.waiting.includes(c.peer))this.waiting.push(c.peer);while(this.waiting.length>=2){const [a,b]=this.waiting.splice(0,2);this.connectionMap.get(a)?.send({type:'match',opponent:b,host:true});this.connectionMap.get(b)?.send({type:'match',opponent:a,host:false})}});c.on('close',()=>{this.connectionMap.delete(c.peer);this.waiting=this.waiting.filter(id=>id!==c.peer)})})}
}
